tz_def('Q25_18_RESP', 'Отлично! Это ваш текущий ранг.');

tz_def('Q25_19', 'Задание 19: Оружие или монеты');
tz_def('Q25_19_DESC', 'Теперь нужно принять решение: мирно торговать или стать грозным воином.<br><br>Для рынка нужен амбар, для казармы — точка сбора.');
tz_def('Q25_19_BUTN', 'Экономика');
tz_def('Q25_19_BUTN1', 'Военное дело');

tz_def('Q25_20', 'Задание 19: Экономика');
